            else:
                nvi_value = nvi[-1]

            nvi.append(nvi_value)

        return nvi

    nvi_series = calculate_negative_volume_index(prices, volumes)
    # The NVI after five days corresponds to the last element of the calculated series.
    final_nvi = nvi_series[-1]
    return round(final_nvi, 2)

