import math

def solve():
    initial_book_value = 120000.0
    salvage_value = 10000.0
    useful_life_years = 5
    year_to_calculate = 3

    def calculate_doubling_declining_balance_depreciation(initial_book_value: float, salvage_value: float, useful_life_years: int, year: int) -> float:
        if year < 1 or year > useful_life_years:
            raise ValueError("Year must be within the useful life of the asset")

        book_value = initial_book_value
        straight_line_rate = 1 / useful_life_years
        double_declining_rate = 2 * straight_line_rate

        depreciation_expense_for_target_year = 0.0

        for current_year in range(1, year + 1):
            # Ensure book_value does not drop below salvage_value before calculating depreciation for the current year
            if book_value <= salvage_value:
                depreciation_expense = 0.0 # No more depreciation possible if book value is already at or below salvage
            else:
                potential_depreciation = book_value * double_declining_rate

                # The book value cannot fall below salvage value. Adjust depreciation if it would.
                if (book_value - potential_depreciation) < salvage_value:
                    depreciation_expense = book_value - salvage_value
                else:
                    depreciation_expense = potential_depreciation

            book_value -= depreciation_expense

            if current_year == year:
                depreciation_expense_for_target_year = depreciation_expense

        return max(0.0, depreciation_expense_for_target_year)

    depreciation_expense = calculate_doubling_declining_balance_depreciation(
        initial_book_value=initial_book_value,
        salvage_value=salvage_value,
        useful_life_years=useful_life_years,
        year=year_to_calculate
    )

    return round(depreciation_expense)

